CREATE TABLE "people" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "normalized_name" TEXT NOT NULL, "phone_number" TEXT NULL, "avatar_path" TEXT NULL, "relationship_tag" TEXT NULL, "notes" TEXT NULL, "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "occasions" ("id" TEXT NOT NULL, "idempotency_key" TEXT NOT NULL, "name" TEXT NOT NULL, "date" INTEGER NOT NULL, "type" TEXT NOT NULL, "notes" TEXT NULL, "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "money_transactions" ("id" TEXT NOT NULL, "idempotency_key" TEXT NOT NULL UNIQUE, "person_id" TEXT NOT NULL REFERENCES people (id), "amount_minor_units" INTEGER NOT NULL, "currency_code" TEXT NOT NULL DEFAULT 'EGP', "direction" TEXT NOT NULL, "kind" TEXT NOT NULL, "date" INTEGER NOT NULL, "note" TEXT NULL, "occasion_id" TEXT NULL REFERENCES occasions (id), "counts_toward_balance" INTEGER NOT NULL DEFAULT 1 CHECK ("counts_toward_balance" IN (0, 1)), "source" TEXT NOT NULL DEFAULT 'manual', "ocr_scan_id" TEXT NULL, "created_at" INTEGER NOT NULL, "edited_at" INTEGER NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "transaction_audit_entries" ("id" TEXT NOT NULL, "transaction_id" TEXT NOT NULL REFERENCES money_transactions (id), "change_type" TEXT NOT NULL, "previous_values_json" TEXT NULL, "changed_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "app_settings" ("id" TEXT NOT NULL, "language_code" TEXT NOT NULL, "theme_mode" TEXT NULL, "glass_enabled" INTEGER NULL CHECK ("glass_enabled" IN (0, 1)), "glass_transparency" TEXT NULL, "glass_intensity" TEXT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "onboarding_status" ("id" TEXT NOT NULL, "is_complete" INTEGER NOT NULL DEFAULT 0 CHECK ("is_complete" IN (0, 1)), "completed_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "finance_categories" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "normalized_name" TEXT NOT NULL, "type" TEXT NOT NULL, "icon" TEXT NOT NULL, "is_default" INTEGER NOT NULL DEFAULT 0 CHECK ("is_default" IN (0, 1)), "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "finance_entries" ("id" TEXT NOT NULL, "idempotency_key" TEXT NOT NULL UNIQUE, "category_id" TEXT NOT NULL REFERENCES finance_categories (id), "type" TEXT NOT NULL, "amount_minor_units" INTEGER NOT NULL, "currency_code" TEXT NOT NULL DEFAULT 'EGP', "date" INTEGER NOT NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL, "edited_at" INTEGER NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "notification_preferences" ("id" TEXT NOT NULL, "is_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("is_enabled" IN (0, 1)), "budget_warnings_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("budget_warnings_enabled" IN (0, 1)), "savings_check_ins_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("savings_check_ins_enabled" IN (0, 1)), "quiet_hours_start_minutes" INTEGER NULL, "quiet_hours_end_minutes" INTEGER NULL, "os_permission_granted" INTEGER NOT NULL DEFAULT 0 CHECK ("os_permission_granted" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "notification_history" ("id" TEXT NOT NULL, "source_type" TEXT NOT NULL, "source_id" TEXT NOT NULL, "applicable_period" TEXT NULL, "last_notified_band" TEXT NOT NULL, "last_notified_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "primary_currency_settings" ("id" TEXT NOT NULL, "currency_code" TEXT NOT NULL DEFAULT 'EGP', "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "exchange_rates" ("id" TEXT NOT NULL, "currency_code" TEXT NOT NULL, "relative_to_currency_code" TEXT NOT NULL, "rate_micros" INTEGER NOT NULL, "last_updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "sync_outbox" ("op_id" TEXT NOT NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "op_type" TEXT NOT NULL, "payload_json" TEXT NOT NULL, "base_revision" INTEGER NULL, "depends_on_rank" INTEGER NOT NULL, "status" TEXT NOT NULL, "attempt_count" INTEGER NOT NULL DEFAULT 0, "last_attempt_at" INTEGER NULL, "next_attempt_at" INTEGER NULL, "error_code" TEXT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("op_id"));
CREATE TABLE "sync_record_meta" ("entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "server_revision" INTEGER NULL, "state" TEXT NOT NULL, "last_synced_at" INTEGER NULL, PRIMARY KEY ("entity_type", "entity_id"));
CREATE TABLE "sync_conflicts" ("id" TEXT NOT NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "local_payload_json" TEXT NOT NULL, "server_payload_json" TEXT NOT NULL, "server_revision" INTEGER NOT NULL, "detected_at" INTEGER NOT NULL, "resolved_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "conflict_resolutions" ("id" TEXT NOT NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "chosen_side" TEXT NOT NULL, "discarded_values_json" TEXT NOT NULL, "resolved_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "sync_state" ("id" TEXT NOT NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "notice_shown" INTEGER NOT NULL DEFAULT 0 CHECK ("notice_shown" IN (0, 1)), "owner_id" TEXT NULL, "device_id" TEXT NOT NULL, "last_pulled_revision" INTEGER NOT NULL DEFAULT 0, "bootstrap_enqueued" INTEGER NOT NULL DEFAULT 0 CHECK ("bootstrap_enqueued" IN (0, 1)), "initial_upload_done" INTEGER NOT NULL DEFAULT 0 CHECK ("initial_upload_done" IN (0, 1)), "last_attempt_at" INTEGER NULL, "last_success_at" INTEGER NULL, "consecutive_failures" INTEGER NOT NULL DEFAULT 0, "last_error_code" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "occasion_attachments" ("id" TEXT NOT NULL, "occasion_id" TEXT NOT NULL REFERENCES occasions (id), "file_path" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "ocr_scans" ("id" TEXT NOT NULL, "idempotency_key" TEXT NOT NULL, "source_image_path" TEXT NOT NULL, "crop_bounds" TEXT NULL, "rotation_degrees" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL, "occasion_id" TEXT NULL REFERENCES occasions (id), "default_direction" TEXT NULL, "currency_code" TEXT NOT NULL DEFAULT 'EGP', "created_at" INTEGER NOT NULL, "completed_at" INTEGER NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "candidate_entries" ("id" TEXT NOT NULL, "scan_id" TEXT NOT NULL REFERENCES ocr_scans (id), "status" TEXT NOT NULL DEFAULT 'pendingReview', "person_name" TEXT NOT NULL, "person_name_confidence_kind" TEXT NOT NULL, "person_name_confidence_level" TEXT NOT NULL, "matched_person_id" TEXT NULL REFERENCES people (id), "amount_minor_units" INTEGER NULL, "amount_confidence_kind" TEXT NOT NULL, "amount_confidence_level" TEXT NOT NULL, "direction" TEXT NULL, "direction_confidence_kind" TEXT NOT NULL, "direction_confidence_level" TEXT NOT NULL, "date" INTEGER NULL, "date_confidence_kind" TEXT NOT NULL, "date_confidence_level" TEXT NOT NULL, "notes" TEXT NULL, "raw_ocr_text" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "edited_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "budgets" ("id" TEXT NOT NULL, "idempotency_key" TEXT NOT NULL, "month" TEXT NOT NULL, "expected_income_minor_units" INTEGER NULL, "currency_code" TEXT NOT NULL DEFAULT 'EGP', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "budget_category_allocations" ("id" TEXT NOT NULL, "idempotency_key" TEXT NOT NULL, "budget_id" TEXT NOT NULL REFERENCES budgets (id), "category_id" TEXT NOT NULL REFERENCES finance_categories (id), "planned_amount_minor_units" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "ai_conversations" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "last_activity_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "ai_messages" ("id" TEXT NOT NULL, "conversation_id" TEXT NOT NULL REFERENCES ai_conversations (id), "sender" TEXT NOT NULL, "content" TEXT NOT NULL, "status" TEXT NOT NULL, "failure_reason" TEXT NULL, "grounding_refs_json" TEXT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "ai_settings" ("id" TEXT NOT NULL, "is_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("is_enabled" IN (0, 1)), "provider_id" TEXT NULL, "has_stored_credential" INTEGER NOT NULL DEFAULT 0 CHECK ("has_stored_credential" IN (0, 1)), "consent_accepted_at" INTEGER NULL, "updated_at" INTEGER NOT NULL, "last_observation_key" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "savings_goals" ("id" TEXT NOT NULL, "idempotency_key" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NULL, "currency_code" TEXT NOT NULL DEFAULT 'EGP', "target_amount_minor_units" INTEGER NOT NULL, "monthly_contribution_minor_units" INTEGER NULL, "target_date" INTEGER NULL, "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "savings_contributions" ("id" TEXT NOT NULL, "idempotency_key" TEXT NOT NULL, "goal_id" TEXT NOT NULL REFERENCES savings_goals (id), "type" TEXT NOT NULL, "amount_minor_units" INTEGER NOT NULL, "entered_amount_minor_units" INTEGER NOT NULL, "entered_currency_code" TEXT NOT NULL, "date" INTEGER NOT NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL, "edited_at" INTEGER NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "savings_contribution_audits" ("id" TEXT NOT NULL, "contribution_id" TEXT NOT NULL REFERENCES savings_contributions (id), "change_type" TEXT NOT NULL, "previous_values_json" TEXT NOT NULL, "changed_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_people_normalized_name ON people (normalized_name);
CREATE INDEX idx_people_archived ON people (is_archived, normalized_name);
CREATE INDEX idx_transactions_person_id ON money_transactions (person_id, deleted_at);
CREATE INDEX idx_transactions_date ON money_transactions (date, deleted_at);
CREATE INDEX idx_transactions_occasion_id ON money_transactions (occasion_id, deleted_at);
CREATE INDEX idx_transactions_ocr_scan_id ON money_transactions (ocr_scan_id, deleted_at);
CREATE INDEX idx_audit_transaction_id ON transaction_audit_entries (transaction_id);
CREATE INDEX idx_finance_categories_normalized_name ON finance_categories (normalized_name, type);
CREATE INDEX idx_finance_entries_category_id ON finance_entries (category_id, deleted_at);
CREATE INDEX idx_finance_entries_date ON finance_entries (date, deleted_at);
CREATE UNIQUE INDEX idx_notification_history_source ON notification_history (source_type, source_id, COALESCE(applicable_period, ''));
CREATE UNIQUE INDEX idx_exchange_rates_pair ON exchange_rates (currency_code, relative_to_currency_code);
CREATE INDEX idx_outbox_ready ON sync_outbox (status, depends_on_rank, created_at);
CREATE INDEX idx_outbox_entity ON sync_outbox (entity_type, entity_id, status);
CREATE INDEX idx_meta_state ON sync_record_meta (state);
CREATE UNIQUE INDEX idx_conflicts_open ON sync_conflicts (entity_type, entity_id) WHERE resolved_at IS NULL;
CREATE UNIQUE INDEX idx_occasions_idempotency_key ON occasions (idempotency_key);
CREATE INDEX idx_occasions_date ON occasions (date, deleted_at);
CREATE INDEX idx_occasions_type ON occasions (type);
CREATE INDEX idx_occasion_attachments_occasion_id ON occasion_attachments (occasion_id, deleted_at);
CREATE UNIQUE INDEX idx_ocr_scans_idempotency_key ON ocr_scans (idempotency_key);
CREATE INDEX idx_ocr_scans_status ON ocr_scans (status, deleted_at);
CREATE INDEX idx_candidate_entries_scan_id ON candidate_entries (scan_id);
CREATE UNIQUE INDEX idx_budgets_idempotency_key ON budgets (idempotency_key);
CREATE UNIQUE INDEX idx_budgets_month ON budgets (month) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX idx_budget_allocations_budget_category ON budget_category_allocations (budget_id, category_id);
CREATE UNIQUE INDEX idx_budget_allocations_idempotency_key ON budget_category_allocations (idempotency_key);
CREATE INDEX idx_budget_allocations_budget_id ON budget_category_allocations (budget_id);
CREATE INDEX idx_ai_messages_conversation_created ON ai_messages (conversation_id, created_at);
CREATE UNIQUE INDEX idx_savings_goals_idempotency_key ON savings_goals (idempotency_key);
CREATE UNIQUE INDEX idx_savings_contributions_idempotency_key ON savings_contributions (idempotency_key);
CREATE INDEX idx_savings_contributions_goal_id ON savings_contributions (goal_id, deleted_at);
CREATE INDEX idx_savings_contribution_audits_contribution_id ON savings_contribution_audits (contribution_id);
PRAGMA user_version = 11;
